def get_weather_icon(clouds, rain, snow, is_daylight):
    if snow and snow > 0:
        return icon("snow", 26, "#7ec8e3")
    if rain and rain > 0:
        return icon("cloud-rain", 26, "#4a7fb5")
    if not is_daylight:
        return icon("moon", 26, "#516344")
    if clouds > 30:
        return icon("cloud", 26, "#8c8c8c")
    return icon("sun", 26, "#e8a33d")


def metric_card(icon_name, label, value):
    return (
        f"<div class='custom-metric'>"
        f"<div class='custom-metric-icon'>{icon(icon_name, 22)}</div>"
        f"<div class='custom-metric-value'>{value}</div>"
        f"<div class='custom-metric-label'>{label}</div>"
        f"</div>"
    )


